<script>
import sensor from '@system.sensor'
import vibrator from '@system.vibrator'
import prompt from '@system.prompt'
import fetch from '@system.fetch'

export default {
  private: {
    devices: [
      { id: 'light', name: '瀹㈠巺鐏?, zone: '姝ｅ墠鏂? },
      { id: 'ac', name: '绌鸿皟', zone: '鍙冲墠鏂? },
      { id: 'curtain', name: '绐楀笜', zone: '宸﹀墠鏂? },
      { id: 'speaker', name: '闊崇', zone: '鍙充晶' }
    ],
    deviceIndex: 0,
    currentDeviceId: 'light',
    currentDeviceName: '瀹㈠巺鐏?,
    currentDeviceZone: '姝ｅ墠鏂?,
    confidence: 86,
    sensorMode: 'Mock 鏁版嵁杩愯涓?,
    lightLevel: 55,
    temperature: 26,
    curtainOpen: true,
    curtainStateText: '寮€鍚?,
    volume: 38,
    sceneIndex: 0,
    sceneName: '鏃ュ父',
    gestureText: '绛夊緟鎵嬪娍杈撳叆',
    lastCommand: '灏氭湭鍙戦€佹帶鍒舵剰鍥?,
    sensorReady: false,
    accelerometerSamples: 0
  },

  onInit() {
    this.syncCurrentDevice()
    this.trySubscribeSensor()
  },

  onDestroy() {
    this.stopSensor()
  },

  trySubscribeSensor() {
    sensor.subscribeAccelerometer({
      interval: 'ui',
      callback: (ret) => {
        this.sensorReady = true
        this.accelerometerSamples += 1
        this.sensorMode = '鐪熷疄鍔犻€熷害璁￠噰闆嗕腑'
        this.handleAccelerometer(ret)
      },
      fail: () => {
        this.sensorReady = false
        this.sensorMode = '璁惧涓嶆敮鎸佷紶鎰熷櫒锛屽凡鍚敤 Mock'
      }
    })
  },

  stopSensor() {
    if (this.sensorReady) {
      sensor.unsubscribeAccelerometer()
    }
  },

  handleAccelerometer(ret) {
    const x = ret.x || 0
    const y = ret.y || 0
    const z = ret.z || 0
    const strength = Math.abs(x) + Math.abs(y) + Math.abs(z)
    if (strength > 18 && this.accelerometerSamples % 4 === 0) {
      this.gestureText = '妫€娴嬪埌蹇€熺敥鑵曪紝宸插彇娑堝綋鍓嶆搷浣?
      this.lastCommand = 'cancel'
      this.feedback('short')
    }
  },

  mockPointNext() {
    this.deviceIndex = (this.deviceIndex + 1) % this.devices.length
    this.syncCurrentDevice()
    this.confidence = 82 + ((this.deviceIndex * 5) % 14)
    this.gestureText = '鎶厱鎸囧悜锛? + this.currentDeviceZone
    this.lastCommand = '鍊欓€夎澶囷細' + this.currentDeviceName
    this.feedback('short')
  },

  mockRotateUp() {
    this.applyDelta(1)
  },

  mockRotateDown() {
    this.applyDelta(-1)
  },

  applyDelta(direction) {
    const device = this.devices[this.deviceIndex]
    if (device.id === 'light') {
      this.lightLevel = this.clamp(this.lightLevel + direction * 10, 0, 100)
      this.emitCommand(device, direction > 0 ? 'brightness_up' : 'brightness_down', this.lightLevel)
    } else if (device.id === 'ac') {
      this.temperature = this.clamp(this.temperature + direction, 18, 30)
      this.emitCommand(device, direction > 0 ? 'temperature_up' : 'temperature_down', this.temperature)
    } else if (device.id === 'speaker') {
      this.volume = this.clamp(this.volume + direction * 8, 0, 100)
      this.emitCommand(device, direction > 0 ? 'volume_up' : 'volume_down', this.volume)
    } else {
      this.curtainOpen = direction > 0
      this.syncCurtainState()
      this.emitCommand(device, direction > 0 ? 'curtain_open' : 'curtain_close', this.curtainStateText)
    }
    this.gestureText = direction > 0 ? '璇嗗埆鎵嬪娍锛氶『鏃堕拡杞厱' : '璇嗗埆鎵嬪娍锛氶€嗘椂閽堣浆鑵?
    this.feedback('short')
  },

  mockFlickCancel() {
    this.gestureText = '璇嗗埆鎵嬪娍锛氱敥鑵曞彇娑?
    this.lastCommand = '褰撳墠鍊欓€夎澶囧凡淇濈暀锛屾湭鎵ц鎺у埗'
    this.feedback('short')
  },

  mockFlipScene() {
    const scenes = ['鏃ュ父', '瑙傚奖', '鐫＄湢', '涓撴敞']
    this.sceneIndex = (this.sceneIndex + 1) % scenes.length
    this.sceneName = scenes[this.sceneIndex]
    if (this.sceneName === '瑙傚奖') {
      this.lightLevel = 25
      this.curtainOpen = false
      this.volume = 45
    } else if (this.sceneName === '鐫＄湢') {
      this.lightLevel = 8
      this.temperature = 26
      this.volume = 10
    } else if (this.sceneName === '涓撴敞') {
      this.lightLevel = 72
      this.temperature = 25
      this.volume = 0
    } else {
      this.lightLevel = 55
      this.temperature = 26
      this.curtainOpen = true
      this.volume = 38
    }
    this.syncCurtainState()
    this.gestureText = '璇嗗埆鎵嬪娍锛氱炕鑵曞垏鎹㈠満鏅?
    this.lastCommand = 'scene_switch -> ' + this.sceneName
    this.feedback('long')
  },

  emitCommand(device, action, value) {
    const payload = {
      deviceId: device.id,
      deviceName: device.name,
      action: action,
      value: value
    }
    this.lastCommand = device.name + ' -> ' + action + ' -> ' + value
    this.sendMockCommand(payload)
  },

  sendMockCommand(payload) {
    fetch.fetch({
      url: 'http://127.0.0.1:8787/aiot-command',
      method: 'POST',
      responseType: 'json',
      data: payload,
      success: () => {
        this.lastCommand = this.lastCommand + ' 路 宸插彂閫?
      },
      fail: () => {
        this.lastCommand = this.lastCommand + ' 路 鏈湴妯℃嫙'
      }
    })
  },

  feedback(mode) {
    vibrator.vibrate({
      mode: mode
    })
    prompt.showToast({
      message: this.currentDeviceName,
      duration: 0
    })
  },

  syncCurrentDevice() {
    const device = this.devices[this.deviceIndex]
    this.currentDeviceId = device.id
    this.currentDeviceName = device.name
    this.currentDeviceZone = device.zone
  },

  syncCurtainState() {
    this.curtainStateText = this.curtainOpen ? '寮€鍚? : '鍏抽棴'
  },

  clamp(value, min, max) {
    if (value < min) {
      return min
    }
    if (value > max) {
      return max
    }
    return value
  }
}
</script>

