    ],
    lastPcSeq: 0,
    pcFailCount: 0,
    lastPcPollAt: 0
  },

  onInit() {
    this.syncCurrentDevice()
    this.trySubscribeSensor()
    this.tryInitInterconnect()
    this.startPcCommandPolling()
  },

  onShow() {
    this.startPcCommandPolling()
  },

  onHide() {
    this.pcPollBusy = false
  },

  onDestroy() {
    this.stopPcCommandPolling()
    this.stopSensor()
  },

  trySubscribeSensor() {
    sensor.subscribeAccelerometer({
      interval: 'ui',
      callback: (ret) => {
        this.sensorReady = true
        this.accelerometerSamples += 1
        this.sensorMode = '真实加速度计采集中'
