  tryInitInterconnect() {
    try {
      this.connect = interconnect.instance()
      this.bridgeState = 'AIoT 通道：手机连接检测中'
      this.connect.onopen = () => {
        this.connectReady = true
        this.bridgeState = 'AIoT 通道：interconnect 已连接'
      }
      this.connect.onclose = () => {
        this.connectReady = false
        this.bridgeState = 'AIoT 通道：连接断开，回落 Mock'
      }
      this.connect.onerror = () => {
        this.connectReady = false
        this.bridgeState = 'AIoT 通道：等待手机端'
      }
      this.connect.onmessage = (data) => {
        this.bridgeState = 'AIoT 回执：' + data.data
      }
      this.connect.getReadyState({
