          this.connectReady = data.status === 1
          this.bridgeState = this.connectReady ? 'AIoT 通道：interconnect 已连接' : 'AIoT 通道：本地 Mock'
        },
        fail: () => {
          this.connectReady = false
          this.bridgeState = 'AIoT 通道：本地 Mock'
        }
      })
    } catch (e) {
      this.connectReady = false
      this.bridgeState = 'AIoT 通道：本地 Mock'
    }
  },

  stopSensor() {
    if (this.sensorReady) {
      sensor.unsubscribeAccelerometer()
    }
    if (this.compassReady && sensor.unsubscribeCompass) {
      sensor.unsubscribeCompass()
    }
  },

  startPcCommandPolling() {
    if (this.pcPollTimer) {
      clearInterval(this.pcPollTimer)
    }
    if (this.pcWatchdogTimer) {
      clearInterval(this.pcWatchdogTimer)
    }
    this.bridgeState = 'AIoT 通道：等待 PC 上位机命令'
    this.pollPcCommand()
    this.pcPollTimer = setInterval(() => {
      this.pollPcCommand()
    }, 800)
    this.pcWatchdogTimer = setInterval(() => {
      this.recoverPcPollingIfNeeded()
    }, 3000)
  },

  stopPcCommandPolling() {
    if (this.pcPollTimer) {
      clearInterval(this.pcPollTimer)
      this.pcPollTimer = null
    }
    if (this.pcWatchdogTimer) {
      clearInterval(this.pcWatchdogTimer)
      this.pcWatchdogTimer = null
    }
  },

  pollPcCommand() {
    if (this.pcPollBusy) {
      return
    }
    this.pcPollBusy = true
    this.lastPcPollAt = Date.now()
    const url = this.pcCommandUrls[this.pcCommandUrlIndex]
    fetch.fetch({
      url: url,
      method: 'GET',
      responseType: 'json',
      success: (ret) => {
        this.pcPollBusy = false
        this.pcFailCount = 0
        this.bridgeState = 'AIoT 通道：PC 上位机已连接'
        this.handlePcCommandPayload(ret.data)
      },
      fail: () => {
        this.pcPollBusy = false
        this.pcFailCount += 1
        if (this.pcFailCount >= 3) {
          this.pcFailCount = 0
          this.pcCommandUrlIndex = (this.pcCommandUrlIndex + 1) % this.pcCommandUrls.length
        }
        this.bridgeState = 'AIoT 通道：等待 PC 上位机'
      }
    })
  },

  recoverPcPollingIfNeeded() {
    const now = Date.now()
    if (this.pcPollBusy && now - this.lastPcPollAt > 2500) {
      this.pcPollBusy = false
      this.bridgeState = 'AIoT 通道：轮询看门狗已恢复'
      this.pollPcCommand()
      return
    }
    if (!this.pcPollTimer) {
      this.startPcCommandPolling()
    }
  },

  handlePcCommandPayload(data) {
    let payload = data
    if (typeof data === 'string') {
      try {
        payload = JSON.parse(data)
      } catch (e) {
        return
      }
    }
    if (!payload || !payload.command) {
      return
    }
    this.lastPcSeq = payload.seq || (this.lastPcSeq + 1)
    this.applyPcCommand(payload)
  },

  applyPcCommand(payload) {
    const command = payload.command
    const label = payload.label
    const accel = payload.accel
    const nextConfidence = typeof payload.confidence === 'number' ? payload.confidence : this.estimateConfidence(command)
    this.confidence = nextConfidence
    this.confidenceText = '置信度阈值：' + this.confidenceThreshold + '%，当前 ' + this.confidence + '%'
    this.pipelineText = payload.pipeline || this.createPipelineText(command)
    if (accel) {
      this.accelText = 'x ' + this.formatAxis(accel.x || 0) + ' / y ' + this.formatAxis(accel.y || 0) + ' / z ' + this.formatAxis(accel.z || 0)
    }
    this.sensorMode = 'PC Mock 手势输入：' + (label || command)
    this.bridgeState = 'AIoT 通道：执行上位机命令 #' + this.lastPcSeq
    this.lastInputText = (payload.inputSource || 'PC/MCU') + ' -> ' + (label || command)

    if (command === 'reset_state') {
      this.resetDemoState(payload.targetDeviceId)
    } else if (command === 'sync_config') {
      this.applyConfigSync(payload)
    } else if (command === 'custom_action') {
      this.syncTargetFromPc(payload.targetDeviceId)
      this.applyCustomAction(payload.actionDef || {})
    } else if (command === 'sensor_sample') {
      this.mockSensorSample(label)
    } else if (command === 'calibrate_space') {
      this.mockCalibrateSpace()
    } else if (this.shouldFilterLowConfidence(command)) {
      this.filterLowConfidenceCommand(command, label)
    } else if (command === 'point_next') {
      this.syncTargetFromPc(payload.targetDeviceId)
      this.mockPointNext(false)
    } else {
      this.syncTargetFromPc(payload.targetDeviceId)
      if (command === 'rotate_cw' || command === 'rotate_up') {
        this.mockRotateUp()
      } else if (command === 'rotate_ccw' || command === 'rotate_down') {
        this.mockRotateDown()
      } else if (command === 'swing_up') {
        this.mockSwingOpen()
      } else if (command === 'swing_down') {
        this.mockSwingClose()
      } else if (command === 'neutral_return') {
        this.mockNeutralReturn()
      } else if (command === 'flick_cancel') {
        this.mockFlickCancel()
      } else if (command === 'flip_scene') {
        this.mockFlipScene()
      } else if (command === 'low_confidence_test') {
        this.filterLowConfidenceCommand(command, label)
      } else {
        this.gestureText = '未知 PC Mock 命令：' + command
        this.markIntent('未知上位机命令', command)
      }
    }
    this.sendPcCommandAck(command, label)
  },

  estimateConfidence(command) {
    if (command === 'neutral_return') {
      return 96
    }
    if (command === 'point_next') {
      return 88
    }
    if (command === 'flip_scene') {
      return 91
    }
    if (command === 'flick_cancel') {
      return 90
    }
    if (command === 'low_confidence_test') {
      return 52
    }
    return 86
  },

  createPipelineText(command) {
    if (command === 'neutral_return') {
      return '识别流程：采样 -> 回正检测 -> 过滤完成'
    }
    if (command === 'calibrate_space') {
      return '识别流程：采样 -> 方位绑定 -> 空间映射更新'
    }
    return '识别流程：采样 -> 分段 -> 手势分类 -> AIoT 执行'
  },

  shouldFilterLowConfidence(command) {
    if (command === 'neutral_return' || command === 'reset_state' || command === 'calibrate_space') {
      return false
    }
    return this.confidence < this.confidenceThreshold
  },

  filterLowConfidenceCommand(command, label) {
    this.gestureText = '疑似手势：' + (label || command)
    this.lastCommand = '置信度 ' + this.confidence + '% 低于阈值，未触发任何设备控制'
    this.pipelineText = '识别流程：采样 -> 低置信判断 -> 误触过滤'
    this.markIntent('误触保护已生效', this.lastCommand)
    this.feedback('short')
  },

  mockLowConfidenceTest() {
    this.confidence = 52
    this.confidenceText = '置信度阈值：' + this.confidenceThreshold + '%，当前 ' + this.confidence + '%'
    this.filterLowConfidenceCommand('low_confidence_test', '误触测试')
