        Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
    }
}

function Stop-DeviceVapp {
    Write-Host "Stop stale device vapp/app processes if present..."
    $psLines = & $adb -s emulator-5554 shell ps 2>$null
    $pids = @()
    foreach ($line in $psLines) {
        if ($line -match 'vapp app/com\.application\.watch\.demo' -or $line -match 'com\.application\.watch\.demo') {
            $parts = ($line -split '\s+') | Where-Object { $_ -ne '' }
            if ($parts.Count -gt 0 -and $parts[0] -match '^\d+$') { $pids += [int]$parts[0] }
        }
    }
    $pids | Select-Object -Unique | Sort-Object -Descending | ForEach-Object {
        Write-Host "Kill device pid $_"
        & $adb -s emulator-5554 shell "kill $_" | Out-Null
    }
    Start-Sleep -Seconds 1
