const fs = require('fs');

const uxPath = 'E:/OPEN_Vela/Projects/test_demo/src/pages/index/index.ux';
let text = fs.readFileSync(uxPath, 'utf8');

const css = `

/* Final glyph-safe title pass: prevent Chinese title clipping on rectangular watch. */
.hero {
  height: 76px;
  padding-top: 0;
  padding-bottom: 6px;
}

.eyebrow {
  height: 13px;
  line-height: 13px;
  font-size: 10px;
  margin-bottom: 0;
}

.title {
  height: 40px;
  line-height: 40px;
  font-size: 21px;
  margin-bottom: 0;
  text-align: center;
}

.subtitle {
  height: 16px;
  line-height: 16px;
  font-size: 10px;
  margin-bottom: 6px;
  text-align: center;
}

.home-panel {
  padding-top: 7px;
}
`;

if (!text.includes('Final glyph-safe title pass')) {
  text = text.replace('</style>', css + '\n</style>');
}

fs.writeFileSync(uxPath, text, 'utf8');
console.log('fixed home title glyph clipping');

